### Step 1: Tarjan SCC in `src/graph.rs`

Add a standalone function that takes directed edges and returns SCCs with >1 member (i.e., actual cycles — singletons without self-loops are excluded).

```rust
/// Find strongly connected components with >1 member in a directed graph.
/// Returns each SCC as a sorted vec of node IDs.
pub fn find_import_sccs(edges: &[(i64, i64)]) -> Vec<Vec<i64>> {
    // Build adjacency list
    let mut adj: HashMap<i64, Vec<i64>> = HashMap::new();
    let mut nodes: HashSet<i64> = HashSet::new();
    for &(from, to) in edges {
        adj.entry(from).or_default().push(to);
        nodes.insert(from);
        nodes.insert(to);
    }

    // Tarjan's algorithm state
    let mut index_counter: i64 = 0;
    let mut stack: Vec<i64> = Vec::new();
    let mut on_stack: HashSet<i64> = HashSet::new();
    let mut index: HashMap<i64, i64> = HashMap::new();
    let mut lowlink: HashMap<i64, i64> = HashMap::new();
    let mut sccs: Vec<Vec<i64>> = Vec::new();

    // Iterative Tarjan (avoids stack overflow on deep graphs)
    for &node in &nodes {
        if index.contains_key(&node) { continue; }
        // iterative DFS with explicit frame stack
        // ... (standard iterative Tarjan implementation)
    }

    // Filter to SCCs with >1 member, sort each
    sccs.into_iter()
        .filter(|scc| scc.len() > 1)
        .map(|mut scc| { scc.sort(); scc })
        .collect()
}
```

Uses iterative DFS (not recursive) to avoid stack overflow on large import graphs.

