### Step 6: `compute_import_cycle_membership` in health pipeline

In `src/health/findings.rs`, add:

```rust
fn compute_import_cycle_membership(db: &Db) -> Result<Vec<HealthFinding>> {
    let edges = db.import_edges()?;
    let sccs = crate::graph::find_import_sccs(&edges);

    let mut file_ids_in_cycles: HashSet<i64> = HashSet::new();
    let mut file_cycle_count: HashMap<i64, usize> = HashMap::new();
    for scc in &sccs {
        for &fid in scc {
            file_ids_in_cycles.insert(fid);
            *file_cycle_count.entry(fid).or_default() += 1;
        }
    }

    let findings = file_ids_in_cycles.iter().map(|&file_id| {
        let cycle_count = file_cycle_count[&file_id];
        HealthFinding {
            file_id,
            symbol_id: None,
            biomarker_kind: BiomarkerKind::ImportCycle,
            severity: BiomarkerKind::ImportCycle.default_severity(),
            confidence: 1.0,
            provenance: "computed".into(),
            metric_value: cycle_count as f64,
            threshold: 1.0,
            detail: format!("file participates in {cycle_count} import cycle group(s)"),
        }
    }).collect();

    Ok(findings)
}
```

Wire into `compute_all_health_findings`:
